    if(ex_inst_cycle == 2'd0) begin
        busctrl_req = DATA_READ; busctrl_addr_muxsel = BUSCTRL_ADDR_PC;
        if_pc_modesel = (alu_flag_neg != 1'b1) ? PC_LOAD_IMMEDIATE : PC_INCREASE; //deny interrupt request
