    busctrl_req = OPCODE_READ; busctrl_addr_muxsel = BUSCTRL_ADDR_PC;

    //next program counter operation
    if_pc_modesel = PC_INCREASE;

    //reset instruction cycle?
    ex_inst_cycle_rst = YES;

    //force next opcode nop?
